CREATE TABLE clients (
  id      INTEGER PRIMARY KEY,
  nom     TEXT NOT NULL,
  ville   TEXT,
  email   TEXT UNIQUE
);

SELECT nom, ville
FROM clients;

SELECT nom
FROM clients
WHERE ville = 'Lyon';

SELECT *
FROM clients
WHERE ville = 'Lyon' AND nom LIKE 'M%';

