SELECT nom, ville
FROM clients
ORDER BY ville ASC, nom ASC;

SELECT nom
FROM clients
ORDER BY id DESC
LIMIT 5;

SELECT DISTINCT ville
FROM clients;

SELECT COUNT(*) AS nombre_clients
FROM clients;

SELECT ville, COUNT(*) AS nombre
FROM clients
GROUP BY ville;

SELECT ville, AVG(age) AS age_moyen
FROM clients
GROUP BY ville
HAVING COUNT(*) >= 3;

